CREATE POLICY "Users read own pdfs" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'pdfs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users upload own pdfs" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'pdfs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete own pdfs" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'pdfs' AND (storage.foldername(name))[1] = auth.uid()::text);